var ENT=[["Logstash", "Elastic's log ingestion pipeline."], ["Fluentd", "Unified logging layer in CNCF."], ["Airbyte", "Open-source data integration connectors."], ["RSS feeds", "Syndication formats for update ingestion."], ["Apache Kafka", "Distributed event-streaming platform; the standard backbone for real-time ingestion."], ["Scrapy", "A Python web-crawling framework with spiders, pipelines and politeness controls."], ["Beautiful Soup", "A forgiving Python HTML and XML parser beloved for quick scraping jobs."]];
var TECH=[["Polite crawling", "robots.txt, rate limits and backoff so scrapers do not harm sites."], ["Change detection", "Polling ETags and Last-Modified or diffing snapshots to ingest only deltas."], ["Schema-on-read", "Storing raw events and applying structure at query time."], ["Exactly-once semantics", "Idempotent producers and transactional sinks for reliable streams."], ["Backpressure handling", "Slowing producers when consumers lag to avoid overload."], ["Dead-letter queues", "Parking poison messages for inspection instead of blocking pipelines."], ["Watermarking", "Tracking event-time progress to close windows in stream processing."], ["API pagination harvesting", "Walking cursor and page tokens to exhaust large REST collections."], ["Sitemap-driven discovery", "Using XML sitemaps to enumerate crawlable URLs efficiently."], ["Consent-aware collection", "Honoring opt-outs and licenses when gathering public data."]];
